		/// <summary> Execute Command </summary>		public int CmdExecute(string command, string workingDirectoryPath, bool output = true, bool waitForExit = true) {			using (Process cmd = new Process()) {				cmd.StartInfo = new ProcessStartInfo("cmd.exe", "/c " + command)				{					RedirectStandardInput = true,					RedirectStandardOutput = true,					RedirectStandardError = true,					CreateNoWindow = true,					UseShellExecute = false,					WorkingDirectory = workingDirectoryPath				};				if (output) {					cmd.OutputDataReceived += (s, e) => Console.WriteLine("VsSharp > CmdExecute > OutputDataReceived:{0}", e.Data);					cmd.ErrorDataReceived += (s, e) => Console.WriteLine("VsSharp > CmdExecute > ErrorDataReceived:{0}", e.Data);				}				cmd.Start();				cmd.BeginOutputReadLine();				cmd.BeginErrorReadLine();				Console.WriteLine("VsSharp > CmdExecute >\n\tcmd:{0}\n\thandle:{1}\n\tmainHandle:{2}\n\tmainTitle:{3}", 					command, cmd.Handle, cmd.MainWindowHandle, cmd.MainWindowTitle				);				if (waitForExit) {					cmd.WaitForExit();				}				return cmd.ExitCode;			}		}